export const normalizeRosterId = (id) => {
  if (!id) return '';
  let s = String(id).trim().replace(/\D/g, '');
  if (!s) return '';
  while (s.length < 9) s = '0' + s;
  return s;
};

export const findStudentByRosterId = (id) => {
  const clean = normalizeRosterId(id);
  if (!clean) return null;
  return ROSTER_BY_ID[clean] || null;
};

export const findStudentByName = (name) => {
  if (!name || name.trim().length < 2) return null;
  const clean = name.trim().toLowerCase();
  return ALL_STUDENTS_LIST.find(s => (s.studentName || '').toLowerCase().includes(clean)) || null;
};

